package llm

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"
	"time"
)

func TestGatewayRetryClassification(t *testing.T) {
	for _, tc := range []struct {
		name, contentType, body     string
		status, failures, wantCalls int
		wantError                   bool
	}{
		{"html forbidden recovers", "text/html", "<!DOCTYPE html>\n<html>Gateway unavailable</html>", 403, 1, 2, false},
		{"sniff html forbidden", "text/plain", " \n<!DOCTYPE HTML><html>Blocked</html>", 403, 1, 2, false},
		{"html forbidden exhausts", "text/html", "<html>Blocked</html>", 403, 10, 4, true},
		{"json forbidden permanent", "application/json", `{"error":{"message":"permission denied"}}`, 403, 1, 1, true},
		{"mislabeled json permanent", "text/html", `{"error":{"message":"permission denied"}}`, 403, 1, 1, true},
		{"plain forbidden permanent", "text/plain", "permission denied", 403, 1, 1, true},
		{"unauthorized permanent", "text/html", "<html>Unauthorized</html>", 401, 1, 1, true},
		{"timeout recovers", "text/plain", "request timeout", 408, 1, 2, false},
		{"rate limit recovers", "application/json", `{"error":"rate limited"}`, 429, 1, 2, false},
		{"internal server error recovers", "application/json", `{"error":"internal error"}`, 500, 1, 2, false},
		{"bad gateway recovers", "text/html", "<html>Bad Gateway</html>", 502, 1, 2, false},
		{"service unavailable recovers", "application/json", `{"error":"temporarily unavailable"}`, 503, 1, 2, false},
		{"gateway timeout recovers", "text/plain", "gateway timeout", 504, 1, 2, false},
		{"service unavailable exhausts", "text/plain", "service unavailable", 503, 10, 4, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var calls atomic.Int32
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if int(calls.Add(1)) <= tc.failures {
					w.Header().Set("Content-Type", tc.contentType)
					w.Header().Set("Server", "cloudflare")
					w.Header().Set("Retry-After", "3")
					w.WriteHeader(tc.status)
					fmt.Fprint(w, tc.body)
					return
				}
				fmt.Fprint(w, successResponse("recovered", "test", "stop", 10, 5))
			}))
			defer server.Close()
			client := NewClient(ClientConfig{BaseURL: server.URL, MaxRetries: 3}).(*httpClient)
			var delays []time.Duration
			client.backoffFunc = func(_ context.Context, _ int, delay time.Duration) { delays = append(delays, delay) }
			resp, err := client.ChatCompletion(context.Background(), ChatRequest{Label: "audit 20/22"})
			if (err != nil) != tc.wantError || int(calls.Load()) != tc.wantCalls {
				t.Fatalf("calls=%d error=%v; want calls=%d error=%v", calls.Load(), err, tc.wantCalls, tc.wantError)
			}
			if !tc.wantError && resp.Content != "recovered" {
				t.Fatal(resp)
			}
			if len(delays) != tc.wantCalls-1 {
				t.Fatal("incorrect backoff count", delays)
			}
			for _, delay := range delays {
				if delay != 3*time.Second {
					t.Fatal("Retry-After not respected", delay)
				}
			}
			if tc.failures == 10 && !strings.Contains(err.Error(), "exhausted 3 retries") {
				t.Fatal(err)
			}
		})
	}
}

func TestGatewayRetryCancellation(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		w.Header().Set("Content-Type", "text/html")
		w.WriteHeader(403)
		fmt.Fprint(w, "<html>Gateway blocked</html>")
	}))
	defer server.Close()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	client := NewClient(ClientConfig{BaseURL: server.URL}).(*httpClient)
	client.backoffFunc = func(context.Context, int, time.Duration) { cancel() }
	_, err := client.ChatCompletion(ctx, ChatRequest{})
	if !errors.Is(err, context.Canceled) || calls.Load() != 1 {
		t.Fatalf("calls=%d error=%v", calls.Load(), err)
	}
}

type retryRoundTripper func(*http.Request) (*http.Response, error)

func (f retryRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) { return f(req) }

type interruptedResponseBody struct{}

func (interruptedResponseBody) Read([]byte) (int, error) { return 0, io.ErrUnexpectedEOF }
func (interruptedResponseBody) Close() error             { return nil }

func TestRetryTransportAndInterruptedBody(t *testing.T) {
	for _, failure := range []string{"connection lost", "request timeout", "body interrupted"} {
		t.Run(failure, func(t *testing.T) {
			calls := 0
			client := NewClient(ClientConfig{BaseURL: "https://provider.invalid"}).(*httpClient)
			client.backoffFunc = func(context.Context, int, time.Duration) {}
			client.client.Transport = retryRoundTripper(func(*http.Request) (*http.Response, error) {
				calls++
				if calls == 1 {
					switch failure {
					case "connection lost":
						return nil, io.EOF
					case "request timeout":
						return nil, context.DeadlineExceeded
					default:
						return &http.Response{StatusCode: 200, Header: make(http.Header), Body: interruptedResponseBody{}}, nil
					}
				}
				return &http.Response{StatusCode: 200, Header: make(http.Header), Body: io.NopCloser(strings.NewReader(successResponse("recovered", "test", "stop", 1, 1)))}, nil
			})
			response, err := client.ChatCompletion(context.Background(), ChatRequest{})
			if err != nil || calls != 2 || response.Content != "recovered" {
				t.Fatalf("calls=%d response=%v error=%v", calls, response, err)
			}
		})
	}
}

package llm

import (
	"encoding/json"
	"testing"
)

func TestRepairJSON_CleanInputUnchanged(t *testing.T) {
	in := `{"security_issues":[],"repo_name":"x"}`
	out, changed := RepairJSON(in)
	if changed {
		t.Errorf("clean input should not be changed: out=%q", out)
	}
}

func TestRepairJSON_StripsMarkdownFence(t *testing.T) {
	in := "```json\n{\"security_issues\":[]}\n```"
	out, changed := RepairJSON(in)
	if !changed {
		t.Fatal("expected repair to trigger")
	}
	var m map[string]any
	if err := json.Unmarshal([]byte(out), &m); err != nil {
		t.Fatalf("repaired output should parse: %v\nout=%q", err, out)
	}
}

func TestRepairJSON_StripsPlainFence(t *testing.T) {
	in := "```\n{\"a\":1}\n```"
	out, changed := RepairJSON(in)
	if !changed || out != `{"a":1}` {
		t.Fatalf("got changed=%v out=%q", changed, out)
	}
}

func TestRepairJSON_ExtractsFromProse(t *testing.T) {
	in := `Here is my analysis:

{"security_issues":[],"repo_name":"x"}

Let me know if you need anything else.`
	out, changed := RepairJSON(in)
	if !changed {
		t.Fatal("expected repair to trigger")
	}
	var m map[string]any
	if err := json.Unmarshal([]byte(out), &m); err != nil {
		t.Fatalf("repaired output should parse: %v\nout=%q", err, out)
	}
	if m["repo_name"] != "x" {
		t.Errorf("repo_name = %v, want x", m["repo_name"])
	}
}

func TestRepairJSON_CoercesStringToEmptyArray(t *testing.T) {
	// The exact failure from the Java scan: security_issues as a string.
	in := `{"repo_name":"x","security_issues":"No security issues were found in this chunk.","public_api_routes":[]}`
	out, changed := RepairJSON(in)
	if !changed {
		t.Fatal("expected repair to trigger")
	}
	var m struct {
		SecurityIssues []any `json:"security_issues"`
	}
	if err := json.Unmarshal([]byte(out), &m); err != nil {
		t.Fatalf("repaired output should parse into []any: %v\nout=%q", err, out)
	}
	if len(m.SecurityIssues) != 0 {
		t.Errorf("SecurityIssues = %v, want empty slice", m.SecurityIssues)
	}
}

func TestRepairJSON_CoercesBothArrayFields(t *testing.T) {
	in := `{"security_issues":"none","public_api_routes":"not applicable"}`
	out, changed := RepairJSON(in)
	if !changed {
		t.Fatal("expected repair to trigger")
	}
	var m struct {
		SecurityIssues  []any `json:"security_issues"`
		PublicAPIRoutes []any `json:"public_api_routes"`
	}
	if err := json.Unmarshal([]byte(out), &m); err != nil {
		t.Fatalf("repaired output should parse: %v\nout=%q", err, out)
	}
}

func TestRepairJSON_LeavesRealArraysAlone(t *testing.T) {
	in := `{"security_issues":[{"issue":"x","file_path":"a.go","start_line":1,"end_line":2,"technical_details":"d","severity":5.0,"cwe_id":"CWE-79"}]}`
	out, changed := RepairJSON(in)
	if changed {
		t.Errorf("valid array should not be coerced: out=%q", out)
	}
}

func TestExtractJSONObject_IgnoresBracesInStrings(t *testing.T) {
	// A path with braces inside a string literal must not confuse depth tracking.
	in := `prose {"k":"a/{b}/c","n":{"m":1}} trailing`
	out, changed := extractJSONObject(in)
	if !changed {
		t.Fatal("expected extraction")
	}
	var m map[string]any
	if err := json.Unmarshal([]byte(out), &m); err != nil {
		t.Fatalf("extracted object should parse: %v\nout=%q", err, out)
	}
	if m["k"] != "a/{b}/c" {
		t.Errorf("k = %v, want a/{b}/c", m["k"])
	}
}

func TestExtractJSONObject_NoObject(t *testing.T) {
	in := "just some prose with no braces"
	_, changed := extractJSONObject(in)
	if changed {
		t.Error("no-brace input should not change")
	}
}

package llm

import (
	"testing"
	"testing/fstest"
)

func TestPromptFingerprintSnapshotsUsedBytes(t *testing.T) {
	fsys := fstest.MapFS{"security_analysis_base.yaml": &fstest.MapFile{Data: []byte("system_message: Original\n")}}
	loader := NewPromptLoader(fsys)
	before, err := loader.Fingerprint()
	if err != nil {
		t.Fatal(err)
	}
	fsys["security_analysis_base.yaml"] = &fstest.MapFile{Data: []byte("system_message: Changed\n")}
	base, err := loader.LoadBasePrompt()
	if err != nil {
		t.Fatal(err)
	}
	if base.SystemMessage != "Original" {
		t.Fatal("fingerprint and prompt bytes diverged")
	}
	after, err := loader.Fingerprint()
	if err != nil {
		t.Fatal(err)
	}
	if after != before {
		t.Fatal("snapshot changed")
	}
	newDigest, err := NewPromptLoader(fsys).Fingerprint()
	if err != nil {
		t.Fatal(err)
	}
	if newDigest == before {
		t.Fatal("template edit did not change fingerprint")
	}
	fsys["unrelated.txt"] = &fstest.MapFile{Data: []byte("not a prompt")}
	unrelated, err := NewPromptLoader(fsys).Fingerprint()
	if err != nil {
		t.Fatal(err)
	}
	if unrelated != newDigest {
		t.Fatal("unrelated file changed prompt identity")
	}
}

package config

import (
	"math"
	"strings"
	"testing"
)

func TestDefaultModelRegistry_ContainsExpectedModels(t *testing.T) {
	registry := DefaultModelRegistry()

	expected := []struct {
		name         string
		contextLimit int
	}{
		{"claude-sonnet-5", 1000000},
		{"claude-opus-4-8", 1000000},
		{"claude-fable-5", 1000000},
		{"claude-haiku-4-5", 200000},
		{"goose-claude-4-6-opus", 200000},
		{"goose-claude-4-7-opus", 1000000},
		{"gpt-5.6", 1050000},
		{"gpt-5.6-sol", 1050000},
		{"gpt-5.6-terra", 1050000},
		{"gpt-5.6-luna", 1050000},
		{"gpt-5.5", 1050000},
		{"gpt-5.5-cyber-preview", 272000},
		{"gpt-5.5-cyber", 272000},
		{"gpt-5.4", 1050000},
		{"gpt-5.4-mini", 400000},
		{"gpt-5.4-nano", 400000},
		{"gemini-3.1-pro-preview", 1048576},
		{"gemini-3.5-flash", 1048576},
		{"gemini-3.1-flash-lite", 1048576},
		{"kimi-k2.6", 128000},
	}

	if len(registry) != len(expected) {
		t.Fatalf("registry length: got %d, want %d", len(registry), len(expected))
	}

	for i, exp := range expected {
		if registry[i].Name != exp.name {
			t.Errorf("registry[%d].Name: got %q, want %q", i, registry[i].Name, exp.name)
		}
		if registry[i].ContextLimit != exp.contextLimit {
			t.Errorf("registry[%d].ContextLimit: got %d, want %d", i, registry[i].ContextLimit, exp.contextLimit)
		}
	}
}

func TestDefaultModelRegistry_ReturnsCopy(t *testing.T) {
	r1 := DefaultModelRegistry()
	r1[0].Name = "mutated"

	r2 := DefaultModelRegistry()
	if r2[0].Name == "mutated" {
		t.Error("DefaultModelRegistry should return a copy, but mutation leaked")
	}
}

func TestLookupModel_ExactName(t *testing.T) {
	tests := []struct {
		query        string
		wantName     string
		wantEndpoint string
		wantFound    bool
	}{
		{"claude-sonnet-5", "claude-sonnet-5", "claude-sonnet-5/invocations", true},
		{"claude-opus-4-8", "claude-opus-4-8", "claude-opus-4-8/invocations", true},
		{"gpt-5.6", "gpt-5.6", "gpt-5.6/invocations", true},
		{"gpt-5.6-sol", "gpt-5.6-sol", "gpt-5.6-sol/invocations", true},
		{"gpt-5.6-terra", "gpt-5.6-terra", "gpt-5.6-terra/invocations", true},
		{"gpt-5.6-luna", "gpt-5.6-luna", "gpt-5.6-luna/invocations", true},
		{"gpt-5.5", "gpt-5.5", "gpt-5.5/invocations", true},
		{"gpt-5.5-cyber-preview", "gpt-5.5-cyber-preview", "gpt-5.5-cyber-preview/invocations", true},
		{"gpt-5.5-cyber", "gpt-5.5-cyber", "gpt-5.5-cyber/invocations", true},
		{"gemini-3.1-pro-preview", "gemini-3.1-pro-preview", "gemini-3.1-pro-preview/invocations", true},
		{"nonexistent-model", "", "", false},
	}

	for _, tt := range tests {
		t.Run(tt.query, func(t *testing.T) {
			m, found := LookupModel(tt.query)
			if found != tt.wantFound {
				t.Fatalf("found: got %v, want %v", found, tt.wantFound)
			}
			if !found {
				return
			}
			if m.Name != tt.wantName {
				t.Errorf("Name: got %q, want %q", m.Name, tt.wantName)
			}
			if m.Endpoint != tt.wantEndpoint {
				t.Errorf("Endpoint: got %q, want %q", m.Endpoint, tt.wantEndpoint)
			}
		})
	}
}

func TestLookupModel_CaseInsensitive(t *testing.T) {
	tests := []struct {
		query    string
		wantName string
	}{
		{"Claude-Sonnet-5", "claude-sonnet-5"},
		{"CLAUDE-SONNET-5", "claude-sonnet-5"},
		{"GPT-5.6", "gpt-5.6"},
		{"GPT-5.6-TERRA", "gpt-5.6-terra"},
		{"GPT-5.5", "gpt-5.5"},
		{"GPT-5.5-CYBER-PREVIEW", "gpt-5.5-cyber-preview"},
		{"Gemini-3.1-Pro-Preview", "gemini-3.1-pro-preview"},
	}

	for _, tt := range tests {
		t.Run(tt.query, func(t *testing.T) {
			m, found := LookupModel(tt.query)
			if !found {
				t.Fatalf("expected to find model for query %q", tt.query)
			}
			if m.Name != tt.wantName {
				t.Errorf("Name: got %q, want %q", m.Name, tt.wantName)
			}
		})
	}
}

func TestLookupModel_PartialMatch(t *testing.T) {
	tests := []struct {
		query    string
		wantName string
	}{
		{"sonnet", "claude-sonnet-5"},
		// Use a direct-Claude fragment so workspace-specific goose aliases do
		// not win the generic longest-match rule.
		{"claude-opus", "claude-opus-4-8"},
		// Multiple gpt entries: longest-match picks the cyber preview alias.
		// Exact GPT queries still hit the exact-match fast path.
		{"gpt", "gpt-5.5-cyber-preview"},
		// The preview Pro ID is the longest Gemini entry.
		{"gemini", "gemini-3.1-pro-preview"},
	}

	for _, tt := range tests {
		t.Run(tt.query, func(t *testing.T) {
			m, found := LookupModel(tt.query)
			if !found {
				t.Fatalf("expected to find model for query %q", tt.query)
			}
			if m.Name != tt.wantName {
				t.Errorf("Name: got %q, want %q", m.Name, tt.wantName)
			}
		})
	}
}

