		}

		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, `{
                        "choices": [{"message": {"content": "", "tool_calls": [{"function": {"arguments": "{\"result\":\"ok\"}"}}]}, "finish_reason": "stop"}],
                        "usage": {"prompt_tokens": 1, "completion_tokens": 1},
